const question = ($json.question || '').trim();
const guidance = 'Try: How many products are low in stock? What is our most expensive product? Which items are out of stock? List all Sensors products.';

if (!question) {
  return [{
    json: {
      question,
      intent: 'unsupported',
      endpoint: '/api/health',
      category: null,
      guidance,
      ai_model: null,
    },
  }];
}

const apiKey = globalThis.process?.env?.OPENAI_API_KEY;
if (!apiKey) {
  throw new Error('OPENAI_API_KEY is not set for n8n. Restart n8n with your OpenAI API key before running Atlas Inventory Bot.');
}

const schema = {
  name: 'atlas_inventory_intent',
  strict: true,
  schema: {
    type: 'object',
    additionalProperties: false,
    properties: {
      intent: {
        type: 'string',
        enum: [
          'total_products',
          'low_stock',
          'out_of_stock',
          'inventory_value',
          'most_expensive_product',
          'products_by_category',
          'list_all_products',
          'unsupported'
        ]
      },
      category: {
        anyOf: [
          { type: 'string' },
          { type: 'null' }
        ]
      }
    },
    required: ['intent', 'category']
  }
};

const openAiResponse = await fetch('https://api.openai.com/v1/responses', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    Authorization: `Bearer ${apiKey}`,
  },
  body: JSON.stringify({
    model: 'gpt-4.1-mini',
    input: [
      {
        role: 'system',
        content: [
          {
            type: 'input_text',
            text: 'You are Atlas Inventory Bot, an inventory assistant for a robotics supply dashboard. Classify the user question into one supported inventory intent. Supported intents: total_products, low_stock, out_of_stock, inventory_value, most_expensive_product, products_by_category, list_all_products, unsupported. Extract a category only when the user asks for products by category. Return JSON only.'
          }
        ]
      },
      {
        role: 'user',
        content: [
          {
            type: 'input_text',
            text: question
          }
        ]
      }
    ],
    text: {
      format: {
        type: 'json_schema',
        name: schema.name,
        strict: schema.strict,
        schema: schema.schema
      }
    }
  })
});

if (!openAiResponse.ok) {
  const errorText = await openAiResponse.text();
  throw new Error(`OpenAI classification failed: ${openAiResponse.status} ${errorText}`);
}

const responsePayload = await openAiResponse.json();
const rawText = responsePayload.output_text || responsePayload.output?.flatMap((item) => item.content || []).find((content) => content.text)?.text || '{}';
const classification = JSON.parse(rawText);

let endpoint = '/api/health';
let category = classification.category ? String(classification.category).trim() : null;

switch (classification.intent) {
  case 'low_stock':
    endpoint = '/api/stats/low-stock';
    break;
  case 'out_of_stock':
    endpoint = '/api/stats/out-of-stock';
    break;
  case 'inventory_value':
    endpoint = '/api/stats/inventory-value';
    break;
  case 'total_products':
    endpoint = '/api/stats/total-products';
    break;
  case 'most_expensive_product':
    endpoint = '/api/stats/most-expensive-product';
    break;
  case 'list_all_products':
    endpoint = '/api/products';
    break;
  case 'products_by_category':
    endpoint = category ? `/api/products?category=${encodeURIComponent(category)}` : '/api/products';
    break;
  default:
    endpoint = '/api/health';
}

return [{
  json: {
    question,
    intent: classification.intent,
    endpoint,
    category,
    guidance,
    ai_model: 'gpt-4.1-mini'
  }
}];

const input = $input.item.json;
const question = input.question || '';
const intent = input.intent;
const category = input.category;
const apiPayload = input.body || input;

if (intent === 'unsupported') {
  return [{
    json: {
      success: false,
      question,
      answer: `I can help with inventory lookups only. ${input.guidance}`,
      data: null
    }
  }];
}

if (apiPayload.success === false) {
  return [{
    json: {
      success: false,
      question,
      answer: apiPayload.message || 'The inventory API request failed.',
      data: apiPayload.data || null,
      errors: apiPayload.errors || null
    }
  }];
}

const data = apiPayload.data;
let answer = '';
let responseData = data;

if (intent === 'low_stock') {
  answer = `There are ${data.low_stock_products} products currently marked as low stock.`;
} else if (intent === 'out_of_stock') {
  answer = `There are ${data.out_of_stock_products} products currently out of stock.`;
} else if (intent === 'most_expensive_product') {
  if (data.product) {
    answer = `The most expensive product is ${data.product.name} at $${Number(data.product.price).toFixed(2)}.`;
    responseData = data.product;
  } else {
    answer = 'No products were found in the catalog.';
  }
} else if (intent === 'inventory_value') {
  answer = `The current total inventory value is $${Number(data.inventory_value).toFixed(2)}.`;
} else if (intent === 'total_products') {
  answer = `We currently have ${data.total_products} products registered in the catalog.`;
} else if (intent === 'list_all_products') {
  const names = data.map((product) => product.name);
  answer = names.length
    ? `Here are all products: ${names.join(', ')}.`
    : 'No products were found in the catalog.';
} else if (intent === 'products_by_category') {
  answer = data.length
    ? `I found ${data.length} ${category} product(s): ${data.map((product) => product.name).join(', ')}.`
    : `No products were found in the ${category} category.`;
}

return [{
  json: {
    success: true,
    question,
    answer,
    data: responseData
  }
}];
